:root {
  --bg:#070B16;
  --bg2:#0C1326;
  --panel:#0F172A;
  --panel2:#131D35;
  --line:rgba(148,163,184,.16);
  --ink:#E5E7EB;
  --ink2:#94A3B8;
  --ink3:#64748B;
  --accent:#38BDF8;
  --krit:#EF4444;
  --myoh:#F97316;
  --pian:#EAB308;
  --pasi:#FBBF24;
  --jerkka:#60A5FA;
  --sanna:#4ADE80;
  --ei:#F87171;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  height: 100%;
}

.nakymat {
  display: inline-flex;
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 3px;
  gap: 2px;
  margin: 8px 0 6px;
}

.nakymat button {
  border: 0;
  background: transparent;
  color: var(--ink2);
  font: 700 12.5px Inter, sans-serif;
  padding: 7px 12px;
  border-radius: 9px;
  cursor: pointer;
}

.nakymat button:hover {
  color: var(--ink);
}

.nakymat button.on {
  background: #0EA5E9;
  color: #04121F;
}

.kokoruutu {
  border: 1px solid var(--line);
  background: transparent;
  color: var(--ink2);
  border-radius: 7px;
  cursor: pointer;
  font-size: 12px;
  padding: 1px 6px;
  margin-left: 6px;
}

.vahvistus {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(2, 6, 16, 0.55);
  backdrop-filter: blur(3px);
}

.vahvistus[hidden] {
  display: none;
}

.vBox {
  width: 420px;
  max-width: 92%;
  background: var(--panel2);
  border: 1px solid rgba(148, 163, 184, 0.35);
  border-radius: 18px;
  padding: 20px 22px;
  box-shadow: 0 30px 70px rgba(0, 0, 0, 0.6);
  animation: nouse 0.25s ease;
}

.vBox h4 {
  margin: 0 0 8px;
  font-size: 16px;
}

.vSiirtyma {
  font-size: 15px;
  font-weight: 700;
  margin: 10px 0;
  color: #E2E8F0;
}

.vIlm {
  font-size: 13px;
  color: var(--ink2);
  line-height: 1.45;
}

.vIlm.lahtee {
  color: #FDE68A;
}

.vNapit {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 16px;
}

.vNapit button {
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: rgba(255, 255, 255, 0.05);
  color: var(--ink);
  border-radius: 10px;
  padding: 9px 14px;
  font: 700 13px Inter, sans-serif;
  cursor: pointer;
}

.vNapit button.paa {
  background: #0EA5E9;
  border-color: #0EA5E9;
  color: #04121F;
}

.vNapit button:disabled {
  opacity: 0.5;
  cursor: default;
}

body {
  background: radial-gradient(1200px 800px at 35% 45%, #0E1A36 0%, var(--bg) 70%);
  color: var(--ink);
  font-family: Inter, system-ui, -apple-system, sans-serif;
  font-size: 14px;
  overflow: hidden;
}

.app {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 380px;
  height: 100vh;
}

.vasen {
  position: relative;
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr);
  min-width: 0;
  min-height: 0;
}

.reuna {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px 0 14px 18px;
  min-height: 0;
  overflow: auto;
  z-index: 2;
}

header {
  padding: 0 0 4px;
}

h1 {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

h1 .logo {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: conic-gradient(from 200deg, transparent 0 70%, var(--accent) 100%);
  border: 2px solid rgba(56, 189, 248, 0.6);
  animation: pyori 4s linear infinite;
}

.alaots {
  color: var(--ink3);
  font-size: 12px;
  margin-top: 2px;
}

.mittarit {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.mittari {
  background: rgba(15, 23, 42, 0.7);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 7px 12px;
  cursor: pointer;
  transition: border-color 0.2s, transform 0.2s;
  display: grid;
  grid-template-columns: 72px 1fr;
  grid-template-rows: auto auto;
  column-gap: 10px;
  align-items: center;
}

.mittari b {
  grid-row: 1/3;
}

.mittari:hover {
  border-color: rgba(148, 163, 184, 0.4);
  transform: translateX(2px);
}

.mittari.on {
  border-color: var(--accent);
}

.mittari b {
  display: block;
  font-size: 24px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
}

.mittari em {
  display: block;
  font-style: normal;
  font-size: 12px;
  font-weight: 700;
  color: #CBD5E1;
  font-variant-numeric: tabular-nums;
  margin-top: 2px;
}

.mittari .delta {
  font-style: normal;
  font-size: 13px;
  font-weight: 800;
  margin-left: 6px;
  vertical-align: middle;
}

.mittari span {
  font-size: 11px;
  color: var(--ink2);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
}

.tutkaWrap {
  flex: 1;
  position: relative;
  min-height: 0;
}

svg#tutka {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.vyo {
  transition: opacity 0.4s;
}

#nimiKulma {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transform: scale(0.96);
  transition: opacity 0.8s ease, transform 1.2s cubic-bezier(0.2, 0.85, 0.25, 1);
  z-index: 0;
}

#nimiKulma.nak {
  opacity: 0.05;
  transform: none;
}

svg#tutka {
  z-index: 1;
}

.rengas {
  fill: none;
  stroke: rgba(148, 163, 184, 0.18);
  stroke-width: 1;
}

.rengas.paa {
  stroke: rgba(148, 163, 184, 0.32);
}

.sade {
  stroke: rgba(148, 163, 184, 0.3);
  stroke-width: 1.2;
}

.sekNimi.pieni {
  font-size: 12px;
  opacity: 0.6;
}

.sekNimi:hover {
  filter: brightness(1.35);
}

.fokusPill {
  position: absolute;
  right: 18px;
  top: 6px;
  z-index: 3;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: rgba(15, 23, 42, 0.85);
  color: var(--ink);
  border-radius: 999px;
  padding: 7px 14px;
  font: 600 12.5px Inter, sans-serif;
  cursor: pointer;
  display: flex;
  gap: 8px;
  align-items: center;
  backdrop-filter: blur(6px);
}

.fokusPill[hidden] {
  display: none;
}

.sekNimi {
  cursor: pointer;
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.sekLuku {
  fill: var(--ink3);
  font-size: 14px;
  font-weight: 600;
}

.nytLbl {
  font-size: 15px;
  letter-spacing: 0.14em;
}

.nytHehku {
  animation: nytSyke 3.2s ease-in-out infinite;
}

@keyframes nytSyke {
  0%, 100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}
.renLbl {
  fill: rgba(203, 213, 225, 0.78);
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.keskus {
  fill: #fff;
  font-weight: 800;
  font-size: 26px;
  letter-spacing: 0.02em;
}

.keskus2 {
  fill: rgba(255, 255, 255, 0.7);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
}

.job {
  transition: transform 1.15s cubic-bezier(0.2, 0.85, 0.25, 1), opacity 0.7s ease;
  cursor: pointer;
}

.job .ydin {
  stroke: rgba(7, 11, 22, 0.85);
  stroke-width: 1.5;
  transition: r 0.25s;
}

.job .kirjain {
  fill: #0B1020;
  font-weight: 800;
  text-anchor: middle;
  dominant-baseline: central;
  pointer-events: none;
}

.job .eiPvm {
  fill: none;
  stroke: #fff;
  stroke-width: 1.4;
  stroke-dasharray: 3 3;
  opacity: 0.75;
}

.job .hehku {
  fill: var(--krit);
  opacity: 0.35;
  transform-box: fill-box;
  transform-origin: center;
  animation: syke 1.8s ease-in-out infinite;
}

.job .sat {
  fill: #fff;
}

.job .satRata {
  fill: none;
  stroke: rgba(255, 255, 255, 0.18);
  stroke-width: 1;
}

.himmea .job {
  opacity: 0.13;
}

.himmea .job.nakyva {
  opacity: 1;
}

.job.valittu .ydin {
  stroke: #fff;
  stroke-width: 3;
}

.sukulinja {
  stroke: #E2E8F0;
  stroke-opacity: 0.6;
  stroke-width: 1.6;
  stroke-dasharray: 5 5;
  animation: virta 1s linear infinite;
  pointer-events: none;
}

.sukurengas {
  fill: none;
  stroke: #E2E8F0;
  stroke-opacity: 0.75;
  stroke-width: 1.6;
  pointer-events: none;
}

@keyframes virta {
  to {
    stroke-dashoffset: -20;
  }
}
.ping {
  fill: none;
  stroke: var(--krit);
  stroke-width: 2;
  transform-box: fill-box;
  transform-origin: center;
  animation: ping 1.3s ease-out forwards;
  pointer-events: none;
}

.ping.sininen {
  stroke: var(--accent);
}

@keyframes ping {
  from {
    transform: scale(1);
    opacity: 0.9;
  }
  to {
    transform: scale(4.2);
    opacity: 0;
  }
}
@keyframes syke {
  0%, 100% {
    transform: scale(1);
    opacity: 0.32;
  }
  50% {
    transform: scale(1.6);
    opacity: 0.05;
  }
}
@keyframes pyori {
  to {
    transform: rotate(360deg);
  }
}
#tip {
  position: absolute;
  pointer-events: none;
  background: rgba(15, 23, 42, 0.96);
  border: 1px solid rgba(148, 163, 184, 0.3);
  border-radius: 14px;
  padding: 12px 14px;
  width: 320px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 0.15s, transform 0.15s;
  z-index: 5;
  backdrop-filter: blur(6px);
}

#tip.nak {
  opacity: 1;
  transform: none;
}

.tTp {
  font-size: 11px;
  color: var(--ink3);
  font-weight: 700;
  letter-spacing: 0.05em;
}

.tAs {
  font-size: 15px;
  font-weight: 700;
  margin: 2px 0;
}

.tAihe {
  color: var(--ink2);
  font-size: 12.5px;
}

.tSyy {
  margin-top: 8px;
  font-weight: 600;
  font-size: 13px;
  display: flex;
  gap: 7px;
  align-items: flex-start;
}

.tAi {
  margin-top: 8px;
  font-size: 12px;
  color: #CBD5E1;
  background: rgba(56, 189, 248, 0.08);
  border-left: 3px solid var(--accent);
  padding: 6px 8px;
  border-radius: 0 8px 8px 0;
}

.tAi i {
  color: var(--accent);
  font-style: normal;
  font-weight: 700;
  font-size: 10.5px;
  letter-spacing: 0.06em;
  display: block;
  margin-bottom: 2px;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 700;
  border-radius: 999px;
  padding: 2px 8px;
  background: rgba(148, 163, 184, 0.14);
  color: #CBD5E1;
}

.dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  display: inline-block;
  flex: none;
}

aside {
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.92), rgba(10, 16, 32, 0.96));
  border-left: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.osio {
  padding: 16px 18px;
  border-bottom: 1px solid var(--line);
}

.osio h3 {
  margin: 0 0 10px;
  font-size: 11px;
  color: var(--ink3);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
}

.chipit {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.03);
  color: var(--ink);
  border-radius: 999px;
  padding: 6px 11px;
  font: 600 12.5px Inter, sans-serif;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.15s;
}

.chip:hover {
  border-color: rgba(148, 163, 184, 0.45);
}

.chip.on {
  background: rgba(56, 189, 248, 0.14);
  border-color: var(--accent);
}

.aika {
  display: flex;
  align-items: center;
  gap: 10px;
}

.aika button {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid rgba(56, 189, 248, 0.5);
  background: rgba(56, 189, 248, 0.12);
  color: var(--accent);
  font-size: 15px;
  cursor: pointer;
  flex: none;
}

.aika input {
  flex: 1;
  accent-color: var(--accent);
}

.aikaLbl {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  min-width: 92px;
  text-align: right;
}

.aikaVihje {
  font-size: 12px;
  color: var(--ink3);
  margin-top: 6px;
}

.lista {
  overflow: auto;
  flex: 1;
  padding: 6px 10px 14px;
}

.lista h3 {
  padding: 10px 8px 4px;
  margin: 0;
  font-size: 11px;
  color: var(--ink3);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
}

.rivi {
  display: grid;
  grid-template-columns: 10px 1fr auto;
  gap: 10px;
  align-items: center;
  padding: 9px 8px;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s;
}

.rivi:hover, .rivi.on {
  background: rgba(148, 163, 184, 0.1);
}

.rivi .n {
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rivi .s {
  font-size: 11.5px;
  color: var(--ink2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rivi .m {
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  font-size: 13px;
  text-align: right;
}

.kortti {
  background: var(--panel2);
  border: 1px solid rgba(148, 163, 184, 0.25);
  border-radius: 16px;
  padding: 14px;
  margin: 12px 10px 4px;
  animation: nouse 0.35s ease;
}

@keyframes nouse {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}
.toim {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
}

.pvmValinta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 12px;
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(34, 211, 238, 0.08);
  border: 1px solid rgba(34, 211, 238, 0.35);
  font-weight: 600;
  font-size: 12.5px;
}

.pvmValinta select {
  color-scheme: dark;
  background: #0B1222;
  color: var(--ink);
  border: 1px solid rgba(148, 163, 184, 0.35);
  border-radius: 8px;
  padding: 6px 8px;
  font: 600 13px Inter, sans-serif;
  cursor: pointer;
  max-width: 200px;
}

.pvmValinta + .pvmValinta {
  margin-top: 8px;
}

.pvmValinta input {
  color-scheme: dark;
  background: #0B1222;
  color: var(--ink);
  border: 1px solid rgba(148, 163, 184, 0.35);
  border-radius: 8px;
  padding: 6px 8px;
  font: 600 13px Inter, sans-serif;
  cursor: pointer;
}

.suku {
  margin-top: 12px;
  font-size: 12.5px;
}

.suku b {
  display: block;
  font-size: 11px;
  color: var(--ink3);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.sukuRivi {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 6px;
  border-radius: 8px;
  cursor: pointer;
  color: #CBD5E1;
}

.sukuRivi:hover {
  background: rgba(148, 163, 184, 0.12);
}

.luonnos {
  margin-top: 12px;
  background: rgba(167, 139, 250, 0.08);
  border: 1px solid rgba(167, 139, 250, 0.4);
  border-radius: 12px;
  padding: 10px;
}

.luonnos i {
  font-style: normal;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.07em;
  color: #C4B5FD;
  display: block;
  margin-bottom: 6px;
}

.luonnos textarea {
  width: 100%;
  background: #0B1222;
  color: var(--ink);
  border: 1px solid rgba(148, 163, 184, 0.3);
  border-radius: 8px;
  padding: 8px;
  font: 500 12.5px/1.45 Inter, sans-serif;
  resize: vertical;
}

.lHuom {
  font-size: 11px;
  color: var(--ink3);
  margin-top: 6px;
}

.toim button {
  border: 1px solid rgba(148, 163, 184, 0.3);
  background: rgba(255, 255, 255, 0.04);
  color: var(--ink);
  border-radius: 10px;
  padding: 8px 11px;
  font: 600 12.5px Inter, sans-serif;
  cursor: pointer;
}

.toim button.paa {
  background: #0EA5E9;
  border-color: #0EA5E9;
  color: #04121F;
}

.toim button:hover {
  filter: brightness(1.15);
}

.selite {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 7px 8px;
  align-items: center;
  font-size: 12px;
  color: var(--ink2);
}

.selite svg {
  overflow: visible;
}

.seliteBox {
  margin-top: auto;
  background: rgba(15, 23, 42, 0.78);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 10px 14px;
  backdrop-filter: blur(6px);
}

.seliteBox summary {
  cursor: pointer;
  font-size: 11px;
  color: var(--ink3);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  list-style: none;
}

.seliteBox[open] summary {
  margin-bottom: 10px;
}

.huom {
  font-size: 11px;
  color: var(--ink3);
  padding: 10px 18px 14px;
  line-height: 1.5;
}

.toast {
  position: absolute;
  left: 50%;
  bottom: 22px;
  transform: translate(-50%, 20px);
  background: #0EA5E9;
  color: #04121F;
  font-weight: 700;
  padding: 10px 16px;
  border-radius: 12px;
  opacity: 0;
  transition: all 0.3s;
  pointer-events: none;
}

.toast.nak {
  opacity: 1;
  transform: translate(-50%, 0);
}

@media (max-width: 1000px) {
  body {
    overflow: auto;
  }
  .app {
    grid-template-columns: 1fr;
    height: auto;
  }
  .vasen {
    grid-template-columns: 1fr;
  }
  .reuna {
    padding-right: 18px;
  }
  .tutkaWrap {
    height: 100vw;
    min-height: 420px;
  }
  aside {
    border-left: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .job {
    transition: none;
  }
  .job .hehku, h1 .logo {
    animation: none;
  }
  #sweep {
    display: none;
  }
}

