// Työtutka – Etusivun kolmas näkymä (Appsmith Custom widget). Data mallista (haeTutka), toiminnot onToiminto-eventillä.
const A = window.appsmith;
function paivaNyt() {
  const d = new Date();
  d.setHours(12, 0, 0, 0);
  return d;
}
let TANAAN = paivaNyt();
const PV = 864e5,
  R = 470;
const KIRKKAAT = {
  Pasi: '#FBBF24',
  Jerkka: '#60A5FA',
  Sanna: '#4ADE80'
};
let VARIT = Object.assign({}, KIRKKAAT);
const EI = 'Ei vastuuhenkilöä';
const SEKTORIT = [{
  k: 'vastaa',
  n: 'Vastaa asiakkaalle',
  vari: '#F472B6',
  st: ['uusi']
}, {
  k: 'tarjous',
