let fokusAnim = 0;
function asetaFokus(f){
  if (f === fokus) return;
  const vanha = SEKTORIT.map(s => ({a0:s.a0, a1:s.a1})), uusi = kulmat(f);
  fokus = f; asetaKulmat(uusi); paivitaKaikki(); tallennaTila();
  const t0 = performance.now(), id = ++fokusAnim, kesto = 950, ease = t => 1 - Math.pow(1 - t, 3);
  const askel = t => { if (id !== fokusAnim) return; const k = Math.min(1, (t - t0)/kesto), e = ease(k);
    asetaKulmat(vanha.map((v,i) => ({a0:v.a0 + (uusi[i].a0 - v.a0)*e, a1:v.a1 + (uusi[i].a1 - v.a1)*e})));
    piirraTausta(); paivitaTekstit();
    if (k < 1) requestAnimationFrame(askel); else asetaKulmat(uusi); };
