      ilmoitus:!!m.esik.ilmoitus_lahtee, vastaanottaja:m.esik.vastaanottaja, viive:m.esik.viive_min});
  }
  const d = m.d; if (!d || !d.tyot || d.nyt === versio) return;
  versio = d.nyt; TANAAN = paivaNyt();
  if (d.varit){ VARIT = {}; Object.keys(d.varit).forEach(n => VARIT[n] = KIRKKAAT[n] || d.varit[n]); HENK = Object.keys(d.varit).sort().concat([EI]); }
  const vanhat = new Map(TYOT.map(j => [j.id, j]));
  TYOT = d.tyot.map(r => { const j = riviTyoksi(r), v = vanhat.get(j.id); if (v && v.sek === j.sek){ j.th = v.th; j.rho = v.rho; } return j; });
  if (valittu) valittu = TYOT.find(j => j.id === valittu.id) || null;
  document.getElementById('paivitetty').textContent = 'Päivitetty ' + String(d.nyt).slice(11, 16) + ' · päivittyy minuutin välein';
  if (eka){
    eka = false; laskePerusW();
    const t = m.tila || {};
    if (m.henkilo && HENK.includes(m.henkilo)) suodatin = m.henkilo;
    if (t.mittari) mittariSuod = MITTARIT.find(x => x.k === t.mittari) || null;
    if (t.fokus != null && t.fokus >= 0 && t.fokus < SEKTORIT.length) fokus = t.fokus;
    asetaKulmat(kulmat(fokus));
